/// One variant per real expression-operator category the Ruby
/// grammar admits, in the order Grammar.admitted_operators's own `category` field declares them. Every match
/// over this enum in the kernel (rust/expr/src/expr.rs) is written
/// WITHOUT a wildcard `_ =>` arm — see expr.rs's own header for why:
/// a wildcard here would let a newly-admitted capability compile
/// silently into a router that never calls the new file this same
/// regeneration adds a `pub mod` line for above.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum OperatorCategory {
    Logical,
    Membership,
    Comparison,
    Arithmetic,
    SignTest,
    Sized,
    ToString,
    Enumeration,
    PatternMatch,
    Presence,
    Text,
    Positional,
}

impl OperatorCategory {
    /// The `rust/expr/src/expression_operators/<name>.rs` file this
    /// variant names — `hecks measure_kernel_coverage`'s own existence
    /// check reads this, so the file-name spelling here is the ONE
    /// place that ever needs to change if a name is renamed.
    pub const fn module_name(&self) -> &'static str {
        match self {
            Self::Logical => "logical",
            Self::Membership => "membership",
            Self::Comparison => "comparison",
            Self::Arithmetic => "arithmetic",
            Self::SignTest => "sign_test",
            Self::Sized => "sized",
            Self::ToString => "to_string",
            Self::Enumeration => "enumeration",
            Self::PatternMatch => "pattern_match",
            Self::Presence => "presence",
            Self::Text => "text",
            Self::Positional => "positional",
        }
    }

    pub const ALL: &'static [Self] = &[
        Self::Logical,
        Self::Membership,
        Self::Comparison,
        Self::Arithmetic,
        Self::SignTest,
        Self::Sized,
        Self::ToString,
        Self::Enumeration,
        Self::PatternMatch,
        Self::Presence,
        Self::Text,
        Self::Positional,
    ];
}
